def _merge(self, old, new, use_equals=False):
    """Helper to merge which handles merging one value."""
    if old is None:
      return new
    if new is None:
      return old
    if (old == new) if use_equals else (old is new):
      return old
    raise ValueError("Incompatible values: %s != %s" % (old, new))

